import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import{World}from'../world.js';import{findPath}from'../navigation.js';import{FURNISHINGS}from'../households.js';
import {isObservatoryScene} from '../observatory-layout.js';
const source=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
test('every furnished interior has reachable, individually selectable objects and wall-aligned ordinary exits',()=>{const w=new World(source);assert.equal(FURNISHINGS.length,24);let count=0;for(const s of w.data.scenes.filter(s=>s.household)){const used=new Set();for(const o of s.objects.filter(o=>o.type==='furnishing')){count++;assert.ok(!used.has(o.xy.join(',')),s.key+' duplicate interaction');used.add(o.xy.join(','));assert.ok(s.floor[o.xy[1]][o.xy[0]]==='.',o.label);assert.ok(Math.hypot(s.arrive[0]-o.xy[0],s.arrive[1]-o.xy[1])<=1||findPath(s,s.arrive,o.xy,1).length,s.key+' '+o.label);assert.ok(o.text.length>30&&o.detail.length>30);}for(const d of [...s.doors,...s.objects.filter(o=>o.type==='portal')]){if(d.architecturalKind==='stairs')continue;const b=s.household.box;assert.ok(d.wallSide,s.key);assert.ok(d.xy[0]===b.left||d.xy[0]===b.right||d.xy[1]===b.top||d.xy[1]===b.bottom,s.key);}}assert.ok(count>0);for(const s of w.data.scenes.filter(s=>s.household)){const objects=s.household.furnishings.filter(o=>![16,18].includes(o.furniture));assert.ok(objects.length>=Math.min(3,Math.max(1,Math.floor(s.household.floorBase.join('').split('.').length/20))),s.key+' useful fixtures');assert.ok(objects.length<=20,s.key+' no repeated prop-budget cycles');}});
test('shared supply compartments pay once, survive a save roundtrip and never write quest flags',()=>{let dialog;const w=new World(source,{onDialog:d=>dialog=d});const room=w.data.scenes.find(s=>s.objects.some(o=>o.type==='furnishing'&&o.supply));w.state.scene=room.location;w.state.mode='field';if(w.state.story)w.state.story.parcel=true;const o=w.scene.objects.find(o=>o.type==='furnishing'&&o.supply),before=w.state.items[o.supply]||0,flags=JSON.stringify(w.state.flags);w.interact(o);dialog.choices[1].action();assert.equal(w.state.items[o.supply],before+1);dialog.after?.();const save=w.save();w.restore(save);w.state.mode='field';w.interact(w.scene.objects.find(x=>x.householdId===o.householdId));dialog.choices[1].action();assert.equal(w.state.items[o.supply],before+1);assert.equal(JSON.stringify(w.state.flags),flags);});
test('older saves inside newly occupied furniture recover on walkable ground without changing crew or supplies',()=>{const w=new World(source),s=JSON.parse(w.save()),o=w.scene.household.furnishings.find(o=>[0,1,2,3].includes(o.furniture));s.x=o.footprint.x+.5;s.y=o.footprint.y+.5;const crew=JSON.stringify(s.heroes),items=JSON.stringify(s.items),flags=JSON.stringify(s.flags);w.restore(s);assert.ok(w.walkable(w.state.x,w.state.y));assert.equal(JSON.stringify(w.state.heroes),crew);assert.equal(JSON.stringify(w.state.items),items);assert.equal(JSON.stringify(w.state.flags),flags);});
test('room programs do not turn hidden ventilation works into bedrooms or galleries into repair shops',()=>{const w=new World(source);for(const[key,program]of [['vent_house','workshop'],['letter_attic','quarters'],['resonance_gallery','chapel'],['echo_chamber','chapel'],['sanctuary','garden'],['lens_workshop','instrumentworks']]){const s=w.data.scenes.find(s=>s.key===key);assert.equal(s.household.kind,program);assert.ok(s.household.composition.authoredStory);}});
test('old obstacle rectangles become floor rather than rows of identical workbenches',()=>{const w=new World(source);for(const s of w.data.scenes.filter(s=>s.household)){assert.equal(s.household.version,2);assert.ok(!(s.blocks||[]).length);if(['workshop','instrumentworks','carpenter'].includes(s.household.kind))assert.ok(s.household.furnishings.filter(o=>o.furniture===8).length<=Math.max(2,Math.min(6,Math.floor(s.household.floorBase.join('').split('.').length/180))));const fixed=s.household.furnishings.filter(o=>![16,18].includes(o.furniture));for(const o of fixed)for(const p of fixed)if(o!==p){const a=o.footprint,b=p.footprint;assert.ok(!(a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y),s.key+' overlapping furniture');}}});
test('furnishing maker marks refer to physical objects actually bound to the same room',()=>{const w=new World(source);let marks=0;for(const s of w.data.scenes.filter(s=>s.household)){for(const o of s.household.furnishings.filter(o=>o.makerMark)){marks++;assert.ok(s.householdPhysicalSites.some(p=>p.physicalId===o.makerMark.id&&p.physicalRole===o.makerMark.role),s.key+' invented mark');assert.ok(o.semioticDetail.length>40);assert.ok(!o.supply,'a communal supply must retain its original ownership message');}}const sites=w.data.scenes.filter(s=>s.household&&!s.originId).flatMap(s=>s.householdPhysicalSites.filter(p=>['source','device'].includes(p.physicalRole)));assert.equal(marks,sites.length);assert.ok(marks>0);});

test('past-era rooms keep their layouts or authored observatory terraces without present-day portable-lore stamps or clues',()=>{const w=new World(source);let observatories=0;for(const s of w.data.scenes.filter(s=>s.originId)){if(isObservatoryScene(s)){observatories++;assert.equal(s.household,undefined);assert.equal(s.householdPhysicalSites,undefined);}else assert.deepEqual(s.householdPhysicalSites,[]);for(const o of [...s.objects,...(s.household?.furnishings||[])]){assert.equal(o.makerMark,undefined);assert.equal(o.semioticDetail,undefined);}}assert.equal(observatories,2);});

test('every hidden room uses its authored purpose and keeps bedrooms out of stores, workshops and waiting rooms',()=>{const w=new World(source),kinds=['workshop','quarters','cistern','chapel','archive','mess','garden','cistern','store','quarters','cargo','kitchen','nursery','washroom','tailor','listening','optics','workshop','tailor','waiting','pottery','listening','printshop','music'];for(let i=0;i<24;i++){const s=w.scenes.get(701+i);assert.equal(s.household.kind,kinds[i],s.title);assert.ok(s.household.composition.authoredStory);if(!['quarters','nursery'].includes(kinds[i]))assert.ok(!s.household.furnishings.some(o=>[0,11].includes(o.furniture)),s.title+' inappropriate bed');}});

test('the original communal stock stays claimed after an old save enters a recomposed room',async()=>{const{installFieldFeedback}=await import('../field-feedback.js'),receipt=JSON.parse(fs.readFileSync(new URL('../../../../development/architecture/ROOM_COMPOSITION_V5.json',import.meta.url))),w=new World(source);w.state.story.parcel=true;w.state.story.firstCore=true;w.state.chapter=24;w.state.household={examined:[],opened:receipt.retainedSupplyCompartments.map(o=>o.id),openFurniture:[]};installFieldFeedback(w,()=>{});const items=JSON.stringify(w.state.items);for(const old of receipt.retainedSupplyCompartments){const s=w.scenes.get(old.room),o=s.household.furnishings.find(o=>o.householdId===old.id);assert.ok(o);assert.deepEqual(o.footprint,old.footprint);assert.equal(o.supply,old.item);w.state.scene=s.location;w.state.x=o.xy[0]+.5;w.state.y=o.xy[1]+.5;w.state.mode='field';w.interact(o);assert.equal(JSON.stringify(w.state.items),items);}});
